<div class="container py-4" dir="rtl"><h2>{{ isset($shift)?'تعديل الوردية':'إضافة وردية' }}</h2>@if($errors->any())<div class="alert alert-danger">{{ $errors->first() }}</div>@endif<form method="post" action="{{ isset($shift)?route('shifts.update',$shift):route('shifts.store') }}" class="card">@csrf @if(isset($shift))@method('put')@endif<div class="card-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">اسم الوردية</label><input required name="shift_name" class="form-control" value="{{ old('shift_name',$shift->shift_name??'') }}"></div><div class="col-md-3"><label class="form-label">البداية</label><input required type="time" name="start_time" class="form-control" value="{{ old('start_time',isset($shift)?substr($shift->start_time,0,5):'') }}"></div><div class="col-md-3"><label class="form-label">النهاية</label><input required type="time" name="end_time" class="form-control" value="{{ old('end_time',isset($shift)?substr($shift->end_time,0,5):'') }}"></div><div class="col-md-3"><label class="form-label">فترة السماح بالدقائق</label><input required type="number" min="0" max="240" name="grace_minutes" class="form-control" value="{{ old('grace_minutes',$shift->grace_minutes??0) }}"></div><div class="col-md-3"><label class="form-label">الراحة بالدقائق</label><input required type="number" min="0" max="480" name="break_minutes" class="form-control" value="{{ old('break_minutes',$shift->break_minutes??0) }}"></div><div class="col-md-3"><label class="form-label">معامل الإضافي</label><input required type="number" step="0.05" min="0.5" max="5" name="overtime_multiplier" class="form-control" value="{{ old('overtime_multiplier',$shift->overtime_multiplier??1.5) }}"></div><div class="col-md-3"><label class="form-label">الحالة</label><select name="status" class="form-select"><option value="open" @selected(old('status',$shift->status??'open')==='open')>مفتوح</option><option value="closed" @selected(old('status',$shift->status??'open')==='closed')>مغلق</option></select></div><div class="col-12"><label class="form-label d-block">أيام العمل</label>@foreach([0=>'الأحد',1=>'الإثنين',2=>'الثلاثاء',3=>'الأربعاء',4=>'الخميس',5=>'الجمعة',6=>'السبت'] as $day=>$label)<label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="work_days[]" value="{{ $day }}" @checked(in_array($day,old('work_days',$shift->work_days??[0,1,2,3,4,5,6])))>{{ $label }}</label>@endforeach</div><div class="col-12"><input type="hidden" name="crosses_midnight" value="0"><label class="form-check"><input class="form-check-input" type="checkbox" name="crosses_midnight" value="1" @checked(old('crosses_midnight',$shift->crosses_midnight??false))>وردية تمتد إلى اليوم التالي</label></div></div></div><div class="card-body pt-0"><button class="btn btn-primary">حفظ الوردية</button> <a href="{{ route('shifts.index') }}" class="btn btn-outline-secondary">رجوع</a></div></form></div>
